A('1962-02-huongdien', '1962-02', VH, 'Kiến Tường. Saigon troops with helicopters and M113 armored carriers hit the Hương Điền liaison station, in February: a squad lost.', 'III, 215', when='Feb.', place='huong-dien', also=OP, check='the day.')
A('1962-0521-tanhoa', '1962-05-21', VH, 'Kiến Tường. Saigon troops hit Tân Hòa, Zone 4, May 21, where Companies 3 and 4 of Battalion 261 were training: four 12.7-mm machine guns and a mortar destroyed or taken.', 'III, 215', place='tan-hoa', also=OP)
A('1962-0819-tanhoadong', '1962-08-19', VH, 'Mỹ Tho. Saigon troops by surprise swoop on Region 8\'s recruit training school at Tân Hòa Đông, Châu Thành, Aug. 19.', 'III, 215', place='tan-hoa-dong', also=OP)
